'use client'
import { useEffect, useState } from 'react'
import Link from 'next/link'
import { motion } from 'framer-motion'
import { supabase, type ForumThread } from '@/lib/supabase'
import { MOCK_THREADS } from '@/lib/mock-data'

const USE_MOCK = true // set false to fetch from Supabase

const ALERT: Record<string, { color: string; label: string }> = {
  watch:  { color: 'var(--gold)',   label: 'Seguimiento' },
  alert:  { color: 'var(--warn)',   label: 'Alerta'      },
  urgent: { color: 'var(--bad)',    label: 'Urgente'     },
}
const TABS = ['Recientes', 'Más urgentes', 'Con respuestas'] as const

export default function ForoPage() {
  const [threads, setThreads] = useState<ForumThread[]>([])
  const [loading, setLoading] = useState(true)
  const [tab, setTab] = useState<typeof TABS[number]>('Recientes')

  useEffect(() => {
    setLoading(true)
    if (USE_MOCK) { setThreads(MOCK_THREADS); setLoading(false); return }
    supabase.from('forum_threads').select('*')
      .order(tab === 'Más urgentes' ? 'alert_level' : tab === 'Con respuestas' ? 'reply_count' : 'created_at', { ascending: false })
      .limit(80)
      .then(({ data }) => { setThreads((data ?? []) as ForumThread[]); setLoading(false) })
  }, [tab])

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.3 }}
      style={{ display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden', background: 'var(--bg)' }}>

      {/* Bar */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '0 20px', height: 46, borderBottom: '1px solid var(--line-2)', flexShrink: 0, background: 'var(--bg-2)', position: 'relative' }}>
        {/* Gradient accent line */}
        <div style={{ position: 'absolute', bottom: -1, left: 0, right: 0, height: 1, background: 'linear-gradient(90deg, var(--accent), transparent 60%)', opacity: 0.5, pointerEvents: 'none' }} />

        <h1 style={{ fontFamily: 'var(--serif)', fontSize: 22, fontWeight: 900, letterSpacing: '-0.02em', color: 'var(--text)', flexShrink: 0 }}>
          Tribuna
        </h1>
        <span style={{ fontFamily: 'var(--mono)', fontSize: 8, letterSpacing: '0.12em', textTransform: 'uppercase', color: 'var(--text-3)', borderLeft: '1px solid var(--line-2)', paddingLeft: 14 }}>
          Investigación colaborativa
        </span>

        {/* Tabs */}
        <div style={{ marginLeft: 'auto', display: 'flex', gap: 2 }}>
          {TABS.map(t => (
            <button key={t} onClick={() => setTab(t)}
              style={{
                padding: '5px 12px',
                background: tab === t ? 'var(--bg-3)' : 'transparent',
                color: tab === t ? 'var(--accent)' : 'var(--text-3)',
                border: tab === t ? '1px solid var(--line-2)' : '1px solid transparent',
                cursor: 'pointer', fontFamily: 'var(--mono)', fontSize: 9,
                letterSpacing: '0.1em', textTransform: 'uppercase', transition: 'all .15s',
              }}>
              {t}
            </button>
          ))}
        </div>

        <button
          style={{
            padding: '7px 16px', background: 'transparent',
            border: '1px solid rgba(56,189,248,.4)', color: 'var(--accent)',
            cursor: 'pointer', fontFamily: 'var(--mono)', fontSize: 9,
            letterSpacing: '0.15em', textTransform: 'uppercase', transition: 'all .18s',
          }}
          onMouseEnter={e => { e.currentTarget.style.background = 'rgba(56,189,248,.08)'; e.currentTarget.style.borderColor = 'var(--accent)' }}
          onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.borderColor = 'rgba(56,189,248,.4)' }}>
          + Nuevo hilo
        </button>
      </div>

      {/* List */}
      <div style={{ flex: 1, overflowY: 'auto', background: 'var(--bg-2)' }}>
        <div style={{ padding: '10px 18px', borderBottom: '1px solid var(--line)', display: 'flex', alignItems: 'center', gap: 8, position: 'sticky', top: 0, background: 'var(--bg-2)', zIndex: 1 }}>
          <span style={{ fontFamily: 'var(--mono)', fontSize: 9.5, color: 'var(--text-3)' }}>
            {loading ? '…' : `${threads.length} conversaciones`}
          </span>
        </div>

        {loading ? (
          <div style={{ padding: '12px 20px', display: 'flex', flexDirection: 'column', gap: 4 }}>
            {Array.from({ length: 8 }).map((_, i) => (
              <div key={i} style={{ height: 72, background: 'var(--bg-3)', backgroundImage: 'linear-gradient(90deg,transparent 25%,var(--bg-4) 50%,transparent 75%)', backgroundSize: '200% 100%', animation: 'shimmer 1.5s infinite' }} />
            ))}
          </div>
        ) : threads.length === 0 ? (
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%', gap: 10 }}>
            <span style={{ fontSize: 32 }}>💬</span>
            <span style={{ fontFamily: 'var(--mono)', fontSize: 10, color: 'var(--text-3)', letterSpacing: '0.1em', textTransform: 'uppercase' }}>Sin hilos activos</span>
          </div>
        ) : (
          <motion.div variants={{ hidden:{}, show:{ transition:{ staggerChildren:.04 } } }} initial="hidden" animate="show">
            {threads.map(t => {
              const s = ALERT[t.alert_level] ?? ALERT.watch
              const isUrgent = t.alert_level === 'urgent'
              return (
                <motion.div key={t.id}
                  variants={{ hidden:{ opacity:0, x:-6 }, show:{ opacity:1, x:0, transition:{ duration:.25 } } }}>
                  <Link href={`/foro/${t.id}`}
                    style={{
                      display: 'flex', alignItems: 'flex-start', gap: 12,
                      padding: '13px 18px', borderBottom: '1px solid var(--line)',
                      textDecoration: 'none', transition: 'all .12s',
                      borderLeft: '2px solid transparent',
                    }}
                    onMouseEnter={e => { (e.currentTarget as HTMLElement).style.background = 'var(--bg-3)'; (e.currentTarget as HTMLElement).style.borderLeftColor = 'rgba(56,189,248,.3)' }}
                    onMouseLeave={e => { (e.currentTarget as HTMLElement).style.background = 'transparent'; (e.currentTarget as HTMLElement).style.borderLeftColor = 'transparent' }}>
                    <span style={{
                      flexShrink: 0, fontFamily: 'var(--mono)', fontSize: 7.5,
                      padding: '2px 6px', textTransform: 'uppercase', letterSpacing: '0.12em',
                      border: `1px solid ${s.color}44`, color: s.color, background: `${s.color}10`,
                      marginTop: 2,
                      animation: isUrgent ? 'pulse 1.5s ease-in-out infinite' : 'none',
                    }}>
                      {s.label}
                    </span>
                    <div style={{ flex: 1 }}>
                      <h3 style={{ fontFamily: 'var(--sans)', fontSize: 12.5, fontWeight: 500, lineHeight: 1.35, color: 'var(--text-2)', margin: '0 0 5px', overflow: 'hidden', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical' }}>
                        {t.title}
                      </h3>
                      <div style={{ display: 'flex', gap: 10, fontFamily: 'var(--mono)', fontSize: 8, color: 'var(--text-4)' }}>
                        <span>{t.reply_count} respuestas</span>
                        <span>{new Date(t.created_at).toLocaleDateString('es')}</span>
                        {t.pinned && <span style={{ color: 'var(--accent)' }}>📌 Fijado</span>}
                      </div>
                    </div>
                  </Link>
                </motion.div>
              )
            })}
          </motion.div>
        )}
      </div>
    </motion.div>
  )
}
